// A Kestrel server inside a Hyperlight micro-VM.
//
// Binds 0.0.0.0:8080; the manifest's [run.net] enables networking and
// allows the port, so the host reaches it at http://127.0.0.1:8080.
var builder = WebApplication.CreateEmptyBuilder(new WebApplicationOptions());
builder.WebHost.UseKestrelCore();

var app = builder.Build();
app.Urls.Add("http://0.0.0.0:8080");

app.Run(async context =>
{
    await context.Response.WriteAsync("Hello from hello on Kestrel, inside a Hyperlight micro-VM!\n");
});

Console.WriteLine("Listening on http://127.0.0.1:8080");
await app.RunAsync();

// An Express server inside a Hyperlight micro-VM.
//
// The guest binds 0.0.0.0:8080; hluk backs guest sockets with host sockets,
// so the listener is reachable from the host at http://127.0.0.1:8080. The
// manifest's [run.net] enables networking and allows the port.
const express = require('express');
const app = express();

app.get('/', (req, res) => {
  res.type('text/plain').send('Hello from hello on Express, inside a Hyperlight micro-VM!\n');
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', app: 'hello', isolation: 'hyperlight-micro-vm' });
});

app.listen(8080, '0.0.0.0', () => {
  console.log('Listening on http://127.0.0.1:8080');
});

