"""A Flask server inside a Hyperlight micro-VM.

The guest binds 0.0.0.0:8080; hluk backs guest sockets with host sockets,
so the listener is reachable from the host at http://127.0.0.1:8080. The
manifest's [run.net] enables networking and allows the port.
"""
from flask import Flask, jsonify

app = Flask(__name__)


@app.get("/")
def index():
    return "Hello from hello on Flask, inside a Hyperlight micro-VM!\n"


@app.get("/health")
def health():
    return jsonify(status="ok", app="hello", isolation="hyperlight-micro-vm")


if __name__ == "__main__":
    print("Listening on http://127.0.0.1:8080", flush=True)
    app.run(host="0.0.0.0", port=8080, threaded=True)

// A compact source file (Java 25): the guest runs its main, as `java Main.java` would.
// A static method declared here can also be called from an embedder with
// AppSandbox::call("greet", json) once this file has run.
record Event(String name) {}

record Greeting(String greeting) {}

Greeting greet(Event event) {
    return new Greeting("Hello, " + event.name() + "!");
}

void main() {
    IO.println("Hello from hello!");
    IO.println(greet(new Event("Java " + Runtime.version().feature())).greeting() + " Running inside a Hyperlight micro-VM.");
}

// A script: what it declares stays for the next call, so a handler defined
// here (or in warm_exec, to have it in the snapshot) can be called many
// times from an embedder with AppSandbox::call("handler", json).
function handler(event) {
  return { greeting: `Hello, ${event.name}!` };
}

console.log(`Hello from hello!`);
console.log(JSON.stringify(handler({ name: "QuickJS on Hyperlight" })));

